messages.content:
Tool response:
Tool: search_products
Description: Search for products matching the given query text.
Filter by ExtraCare Member Price if requested and user is a member.
Sort by Best Match (Rating desc, Review Count desc).
Parameters:
    {
      "type": "object",
      "properties": {
        "query": {
          "type": "string",
          "description": "Search query text",
          "title": "Query"
        },
        "filter_type": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Filter type (e.g., 'ExtraCare Member Price')",
          "title": "Filter Type"
        },
        "sort_by": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Sort criteria (e.g., 'Best Match')",
          "title": "Sort By"
        }
      },
      "required": [
        "query"
      ]
    }

Tool response:
Tool: add_item_to_cart
Description: Add a specific product variant to the user's active cart.
Unit price determined by ExtraCare membership.
Parameters:
    {
      "type": "object",
      "properties": {
        "cart_id": {
          "type": "integer",
          "description": "ID of the cart to add item to",
          "title": "Cart Id"
        },
        "product_variant_id": {
          "type": "integer",
          "title": "Product Variant Id"
        },
        "quantity": {
          "type": "integer",
          "title": "Quantity",
          "default": 1
        }
      },
      "required": [
        "cart_id",
        "product_variant_id"
      ]
    }

Tool response:
Tool: create_order
Description: Create a new order based on the contents of an active cart.
Apply CarePass free shipping if user qualifies.
Parameters:
    {
      "type": "object",
      "properties": {
        "cart_id": {
          "type": "integer",
          "title": "Cart Id"
        }
      },
      "required": [
        "cart_id"
      ]
    }
